function Status({ value }: { value: string | null | undefined }) {
  const map: Record<string, string> = { DRAFT: "bg-slate-100 text-slate-700", SENT: "bg-blue-100 text-blue-700", ACCEPTED: "bg-emerald-100 text-emerald-700", CONFIRMED: "bg-blue-100 text-blue-700", DELIVERED: "bg-emerald-100 text-emerald-700", VALIDATED: "bg-emerald-100 text-emerald-700", POSTED: "bg-blue-100 text-blue-700", PAID: "bg-emerald-100 text-emerald-700", LATER: "bg-amber-100 text-amber-800", CANCELLED: "bg-red-100 text-red-700", EXPIRED: "bg-amber-100 text-amber-700" };
  const labels: Record<string, string> = { DRAFT: "Draft", SENT: "Dërguar", ACCEPTED: "Pranuar", CONFIRMED: "Konfirmuar", DELIVERED: "Dorëzuar", VALIDATED: "Validuar", POSTED: "Postuar", PAID: "E paguar", LATER: "Pagesë më vonë", CANCELLED: "Anuluar", EXPIRED: "Skaduar" };
  const status = value ?? "DRAFT";
  return <Badge className={`border-0 font-medium ${map[status] ?? map.DRAFT}`}>{labels[status] ?? status}</Badge>;
}

function PaymentStatus({ value, invoiceStatus }: { value: string | null | undefined; invoiceStatus?: string | null }) {
  const status = value || (invoiceStatus === "PAID" ? "PAID" : "UNPAID");
  const labels: Record<string, string> = { PAID: "E paguar", LATER: "Pagesë më vonë", UNPAID: "E papaguar" };
  const tones: Record<string, string> = { PAID: "bg-emerald-100 text-emerald-700", LATER: "bg-amber-100 text-amber-800", UNPAID: "bg-slate-100 text-slate-700" };
  return <Badge className={`border-0 font-medium ${tones[status] ?? tones.UNPAID}`}>{labels[status] ?? labels.UNPAID}</Badge>;
}

