  const resetSalesInvoiceFilters = () => { setSalesInvoiceSearch(""); setSalesInvoiceCustomerFilter(""); setSalesInvoiceCurrencyFilter("ALL"); setSalesInvoiceDateFrom(""); setSalesInvoiceDateTo(""); setSalesInvoiceMinAmount(""); setSalesInvoiceMaxAmount(""); setSalesInvoiceStatusFilter("ALL"); setSalesPaymentFilter("ALL"); setSalesInvoiceSort("date"); setSalesInvoiceSortDirection("desc"); };
