  const salesRegisterProductIdOptions = useMemo(() => Array.from(new Set((salesRegister as SalesRegisterRow[]).map(row => row.productId).filter((id): id is number => Number.isFinite(id)).map(String))).sort(), [salesRegister]);
  const { data: quotations = [] } = trpc.salesQuotation.list.useQuery({ companyId }); const { data: orders = [] } = trpc.salesOrder.list.useQuery({ companyId }); const { data: deliveries = [] } = trpc.delivery.list.useQuery({ companyId }); const { data: returns = [] } = trpc.salesReturn.list.useQuery({ companyId }); const { data: products = [] } = trpc.product.list.useQuery({ companyId }); const { data: warehouses = [] } = trpc.warehouse.list.useQuery({ companyId });
