      const matchesPayment = salesPaymentFilter === "ALL" || paymentStatus === salesPaymentFilter;
      const matchesStatus = salesInvoiceStatusFilter === "ALL" || invoice.status === salesInvoiceStatusFilter;
      const matchesSearch = !query || `${invoice.docNumber} ${invoice.customerName || ""}`.toLocaleLowerCase("sq-AL").includes(query);
      const matchesCustomer = !salesInvoiceCustomerFilter || String(invoice.customerId || "") === salesInvoiceCustomerFilter;
